'
/* =========================
   ROOT / CARD
   ========================= */

#htmlContent {
  --primary: #0057CE;
  --secondary: #D51A9F;
  --ink: #041225;
  --muted: #64778F;
  --line: #E5E7EB;
  --pos-fill: #EAF2FF;
  --neg-fill: #FCEAF5;

  font-family: ''Segoe UI'', Arial, sans-serif;
  font-size: 14px;
  color: var(--ink);
  background: #FFFFFF;

  width: 498px;
  height: 757px;

  box-sizing: border-box;
  padding: 12px 16px;
  overflow: hidden;
}

#htmlContent * {
  box-sizing: border-box;
}

.card {
  display: flex;
  flex-direction: column;
  position: relative;

  width: 100%;
  height: 100%;
  min-height: 0;

  gap: 8px;
  overflow: hidden;
}

.htmlViewerEntry {
  margin: 0;
  padding: 0;
}

.htmlViewerEntry:empty {
  display: none;
}


/* =========================
   HEADER
   ========================= */

.card-head {
  position: relative;
  flex: 0 0 auto;
  padding-right: 40px;
}

.card-title {
  font-size: 16px;
  font-weight: 600;
}

.card-sub {
  font-size: 13px;
  color: var(--muted);
  margin-top: 7px;
  margin-bottom: 7px;
  line-height: 1.4;
}


/* =========================
   INFORMATION BUTTON
   ========================= */

.info {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 50;
}

.info > summary {
  list-style: none;
  cursor: pointer;

  width: 28px;
  height: 28px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #CBD5E1;
  border-radius: 50%;
  background: #FFFFFF;

  color: var(--muted);
  font-family: ''Segoe UI'', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;

  transition: all 0.15s ease;
}

.info > summary::-webkit-details-marker {
  display: none;
}

.info > summary:hover {
  color: var(--primary);
  border-color: var(--primary);
  background: var(--pos-fill);
}

.info[open] > summary {
  color: #FFFFFF;
  border-color: var(--primary);
  background: var(--primary);
}

.info-panel {
  position: absolute;
  top: 36px;
  right: 0;

  width: 270px;
  padding: 14px;

  background: #FFFFFF;
  border: 1px solid #DCE2EA;
  border-radius: 8px;

  box-shadow: 0 5px 20px rgba(4, 18, 37, 0.13);

  color: var(--ink);
  font-size: 13px;
  line-height: 1.5;

  z-index: 100;
}

.info-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 9px;
}

.info-item {
  font-size: 13px;
  margin-bottom: 7px;
}

.info-item b {
  font-weight: 600;
}

.scale-text {
  color: var(--primary);
}

.fix-text {
  color: var(--secondary);
}

.gem-text {
  color: var(--primary);
}

.mute-text {
  color: var(--muted);
}

.info-note {
  border-top: 1px solid var(--line);
  padding-top: 9px;
  margin-top: 9px;

  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}


/* =========================
   VOLUME VS CONVERSION PLOT
   ========================= */

.plot-wrap {
  position: relative;
  height: 280px;
  flex: 0 0 280px;
}

.plot {
  position: absolute;

  left: 34px;
  right: 8px;
  top: 6px;
  bottom: 26px;

  border-left: 1px solid #CBD5E1;
  border-bottom: 1px solid #CBD5E1;
}

.thr-v {
  position: absolute;
  top: 0;
  bottom: 0;

  border-left: 1px dashed #B9C4D6;
}

.thr-h {
  position: absolute;
  left: 0;
  right: 0;

  border-top: 1px dashed #B9C4D6;
}

.quad {
  position: absolute;

  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  opacity: .75;
}

.quad.tl {
  top: 6px;
  left: 8px;
}

.quad.tr {
  top: 6px;
  right: 8px;
}

.quad.bl {
  bottom: 6px;
  left: 8px;
}

.quad.br {
  bottom: 6px;
  right: 8px;
}


/* =========================
   AXIS LABELS
   ========================= */

.ax-x {
  position: absolute;

  left: 34px;
  right: 8px;
  bottom: 2px;

  text-align: center;
  font-size: 12px;
  color: var(--muted);
}

.ax-y {
  position: absolute;

  left: 4px;
  top: 6px;
  bottom: 26px;
  width: 16px;

  writing-mode: vertical-rl;
  transform: rotate(180deg);

  text-align: center;
  font-size: 12px;
  color: var(--muted);
}


/* =========================
   SCATTER PLOT MARKERS
   ========================= */

.dot {
  position: absolute;

  width: 26px;
  height: 26px;
  margin: 0 0 -13px -13px;

  border-radius: 50%;
  box-sizing: border-box;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 13px;
  font-weight: 600;

  background: #FFFFFF;
}

.dot.scale {
  background: var(--primary);
  color: #FFFFFF;
}

.dot.fix {
  background: var(--secondary);
  color: #FFFFFF;
}

.dot.gem {
  border: 1.5px solid var(--primary);
  color: var(--primary);
}

.dot.mute {
  border: 1.5px solid var(--muted);
  color: var(--muted);
}


/* =========================
   TABLE HEADER
   ========================= */

.q-head,
.q {
  display: grid;

  grid-template-columns:
    26px
    minmax(0, 1fr)
    50px
    56px
    50px
    108px;

  column-gap: 8px;
  align-items: center;
  margin-top: 6px;
}

.q-head {
  flex: 0 0 auto;
  margin-top: 40px;

  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .04em;

  color: var(--muted);
  padding: 0 2px;
}

.q-head span:nth-child(n+3):nth-child(-n+5) {
  text-align: right;
}

.q-head span:nth-child(6) {
  text-align: right;
}


/* =========================
   SOURCE LIST
   ========================= */

.q-list {
  flex: 1 1 auto;
  min-height: 0;

  overflow-y: auto;
  overflow-x: hidden;

  scrollbar-width: thin;
  scrollbar-color: #CFCFCF transparent;
}

.q-list::-webkit-scrollbar {
  width: 6px;
}

.q-list::-webkit-scrollbar-track {
  background: transparent;
}

.q-list::-webkit-scrollbar-thumb {
  background: #CFCFCF;
  border-radius: 3px;
}

.q-list::-webkit-scrollbar-thumb:hover {
  background: #ABABAB;
}


/* =========================
   INDIVIDUAL SOURCE ROWS
   ========================= */

.q {
  min-height: 44px;
  padding: 4px 2px;

  border-bottom: 1px solid #F0F2F6;
}

.q-rank {
  width: 24px;
  height: 24px;

  border-radius: 50%;
  box-sizing: border-box;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 13px;
  font-weight: 600;

  background: #FFFFFF;
}

.q-rank.scale {
  background: var(--primary);
  color: #FFFFFF;
}

.q-rank.fix {
  background: var(--secondary);
  color: #FFFFFF;
}

.q-rank.gem {
  border: 1.5px solid var(--primary);
  color: var(--primary);
}

.q-rank.mute {
  border: 1.5px solid var(--muted);
  color: var(--muted);
}

.q-name {
  font-size: 15px;
  font-weight: 600;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.q-sub {
  font-size: 13px;
  color: var(--muted);
  margin-top: 1px;
}

.q-num {
  text-align: right;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
}

.q-num.up {
  color: var(--primary);
  font-weight: 600;
}

.q-num.down {
  color: var(--secondary);
  font-weight: 600;
}

.q-verdict {
  text-align: right;
}


/* =========================
   VERDICT PILLS
   ========================= */

.pill {
  display: inline-block;

  font-size: 13px;
  font-weight: 600;

  padding: 3px 8px;
  border-radius: 999px;

  white-space: nowrap;
}

.pill.scale {
  background: var(--pos-fill);
  color: var(--primary);
}

.pill.fix {
  background: var(--neg-fill);
  color: var(--secondary);
}

.pill.gem {
  background: #FFFFFF;
  color: var(--primary);

  border: 1px solid var(--primary);
  padding: 2px 7px;
}

.pill.mute {
  background: transparent;
  color: var(--muted);

  font-weight: 400;
  padding: 3px 0;
}


/* =========================
   REMOVED ELEMENTS
   ========================= */

.summary,
.legend {
  display: none !important;
}
'
